import os, pathlib

def tree(root, indent=0, max_depth=4):
    if indent > max_depth:
        return
    try:
        entries = sorted(os.scandir(root), key=lambda e: (e.is_file(), e.name))
    except PermissionError:
        return
    for e in entries:
        print("  " * indent + e.name + ("/" if e.is_dir() else ""))
        if e.is_dir():
            tree(e.path, indent + 1, max_depth)

